//! Response bodies. Every variant produces its frames synchronously from memory-mapped
//! slabs and a request arena; the big ones (`prefetch`, `objects`) are zero-copy slices of
//! the slab files plus a few generated bytes (headers, re-encoded delta distances, the
//! SHA-1 trailer), so the work per frame is the hash and nothing else.

use std::convert::Infallible;
use std::pin::Pin;
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll};

use bytes::{Bytes, BytesMut};
use http_body::{Body as HttpBody, Frame, SizeHint};
use sha1::{Digest, Sha1};

use crate::arena::Span;
use crate::frames::{Busy, FRAME_BUF_BYTES, FrameRing};
use crate::mphf::Loc;
use crate::pack::{
    ObjType, encode_entry_header, encode_ofs_delta_header, loose_header, pack_header,
    parse_entry_header,
};
use crate::splice::{GEN_FRAME_BYTES, Plan, SpliceStream};
use crate::zlib::{Deflater, compress_bound};

use super::catalog::Catalog;
use super::json::{decimal_len, put_decimal};
use super::objects::{NO_BASE, resolve_full};
use super::pool::{ArenaGuard, RequestArena};

/// Room a splice stream may need for one generated frame (a large-offset run is 8 bytes
/// per entry of a `GEN_FRAME_BYTES / 4`-entry run, plus headers).
const SPLICE_FRAME_ROOM: usize = GEN_FRAME_BYTES.saturating_mul(2).saturating_add(4096);

/// One object being deflated into chunk-sized frames: `raw ++ zlib(zipped ++ content)`.
/// A pack entry has a raw header (type/size varint) in front of the zlib stream; a loose
/// object has its `"<type> <size>\0"` header inside it. The resolved content stays in the
/// arena until the stream ends, so an object of any size costs a bounded frame per poll.
pub struct Deflating {
    raw: [u8; 10],
    raw_len: usize,
    zipped: [u8; 32],
    zipped_len: usize,
    content: Span,
    /// Arena mark to drop back to once the content has been consumed.
    mark: usize,
    /// 0: still feeding `zipped`; 1: feeding `content`.
    part: u8,
    in_pos: usize,
    started: bool,
    done: bool,
    /// The last step made no progress in a chunk's leftover: ask for a whole chunk.
    want_full: bool,
}

impl Deflating {
    pub fn pack_entry(kind: ObjType, content: Span, mark: usize) -> Self {
        let mut raw = [0u8; 10];
        let raw_len = encode_entry_header(kind, content.len as u64, &mut raw);
        Self {
            raw,
            raw_len,
            zipped: [0u8; 32],
            zipped_len: 0,
            content,
            mark,
            part: 1,
            in_pos: 0,
            started: false,
            done: false,
            want_full: false,
        }
    }

    pub fn loose(kind: ObjType, content: Span, mark: usize) -> Self {
        let mut zipped = [0u8; 32];
        let zipped_len = loose_header(kind, content.len as u64, &mut zipped);
        Self {
            raw: [0u8; 10],
            raw_len: 0,
            zipped,
            zipped_len,
            content,
            mark,
            part: 0,
            in_pos: 0,
            started: false,
            done: false,
            want_full: false,
        }
    }

    fn remaining_input(&self) -> usize {
        match self.part {
            0 => self
                .zipped_len
                .saturating_sub(self.in_pos)
                .saturating_add(self.content.len),
            _ => self.content.len.saturating_sub(self.in_pos),
        }
    }

    /// The next frame; `Ok(None)` once the stream has ended.
    pub fn step(&mut self, ra: &mut RequestArena) -> Result<Option<Bytes>, Busy> {
        if self.done {
            return Ok(None);
        }
        let bound = compress_bound(self.remaining_input()).saturating_add(64);
        let need = if self.want_full {
            FRAME_BUF_BYTES
        } else {
            self.raw_len.saturating_add(bound).min(FRAME_BUF_BYTES)
        };
        let (frames, bytes) = (&mut ra.frames, &ra.bytes);
        let Some(buf) = frames.chunk(need) else {
            return Err(Busy);
        };
        let mut deflater = ra.deflater.take().unwrap_or_else(|| Deflater::new(6));
        if !self.started {
            self.started = true;
            deflater.begin();
            buf.extend_from_slice(self.raw.get(..self.raw_len).unwrap_or(&[]));
        }
        let start = buf.len();
        let room = buf.capacity().saturating_sub(start).min(bound);
        buf.resize(start.saturating_add(room), 0);
        let mut written = 0usize;
        loop {
            let (input, finish) = if self.part == 0 {
                (
                    self.zipped.get(self.in_pos..self.zipped_len).unwrap_or(&[]),
                    false,
                )
            } else {
                (
                    bytes.get(self.content).get(self.in_pos..).unwrap_or(&[]),
                    true,
                )
            };
            let out = buf
                .get_mut(start.saturating_add(written)..start.saturating_add(room))
                .unwrap_or(&mut []);
            let Ok((c, p, end)) = deflater.step(input, out, finish) else {
                // Unreachable for valid input; end the stream rather than loop.
                self.done = true;
                break;
            };
            self.in_pos = self.in_pos.saturating_add(c);
            written = written.saturating_add(p);
            if end {
                self.done = true;
                break;
            }
            if self.part == 0 && c >= input.len() {
                self.part = 1;
                self.in_pos = 0;
                continue;
            }
            if c == 0 && p == 0 {
                // Output full. A step that produced nothing at all needs a bigger run.
                self.want_full = written == 0;
                break;
            }
        }
        buf.truncate(start.saturating_add(written));
        ra.deflater = Some(deflater);
        if self.done {
            ra.bytes.truncate(self.mark);
        }
        Ok(Some(buf.split().freeze()))
    }
}

pub const GPRE_MAGIC: &[u8; 6] = b"GPRE \x01";
pub const CONTENT_TYPE_PREFETCH: &str = "application/x-gvfs-timestamped-packfiles-indexes";
pub const CONTENT_TYPE_PACKFILE: &str = "application/x-git-packfile";
pub const CONTENT_TYPE_LOOSE: &str = "application/x-git-loose-object";
pub const CONTENT_TYPE_JSON: &str = "application/json";

/// Cache of spliced-pack checksums keyed by the selection, so a storm of identical cold
/// clones hashes the 3 GiB baseline once and then streams it by reference only.
type TrailerSlot = (u64, [u8; 20], [u8; 20]);

#[derive(Debug)]
pub struct TrailerCache {
    slots: Mutex<[TrailerSlot; 64]>,
}

impl Default for TrailerCache {
    fn default() -> Self {
        Self::new()
    }
}

impl TrailerCache {
    pub fn new() -> Self {
        Self {
            slots: Mutex::new([(0u64, [0u8; 20], [0u8; 20]); 64]),
        }
    }

    pub fn get(&self, key: u64) -> Option<([u8; 20], [u8; 20])> {
        let slots = self.slots.lock().ok()?;
        slots
            .iter()
            .find(|(k, _, _)| *k == key && key != 0)
            .map(|(_, p, i)| (*p, *i))
    }

    pub fn put(&self, key: u64, pack: [u8; 20], idx: [u8; 20]) {
        if key == 0 {
            return;
        }
        if let Ok(mut slots) = self.slots.lock() {
            let i = (key % 64) as usize;
            if let Some(s) = slots.get_mut(i) {
                *s = (key, pack, idx);
            }
        }
    }
}

/// A stable key for a prefetch selection (slab seqs, timestamps and sizes).
pub fn selection_key(plan: &Plan) -> u64 {
    let mut h: u64 = 0xCBF2_9CE4_8422_2325;
    for s in plan.slabs.iter() {
        for v in [s.meta.seq, s.meta.end_ts, u64::from(s.meta.object_count)] {
            h ^= v;
            h = h.wrapping_mul(0x0000_0100_0000_01B3);
        }
    }
    h | 1
}

/// Computes and caches the checksums of the cold-clone selection of `cat` (the baseline,
/// the pyramid, the live slab), so that the first cold clone after a catalog change does
/// not pay for hashing gigabytes. Returns the time spent, `None` when nothing was to do.
pub fn warm_cold_selection(
    cat: &Catalog,
    cache: &TrailerCache,
) -> Option<(std::time::Duration, u64)> {
    let list = cat.select(0, false).ok()?;
    if list.is_empty() {
        return None;
    }
    let plan = Plan::new(list).ok()?;
    if plan.is_passthrough() {
        return None;
    }
    let key = selection_key(&plan);
    if cache.get(key).is_some() {
        return None;
    }
    let t0 = std::time::Instant::now();
    let bytes = plan.pack_len.saturating_add(plan.idx_len);
    let mut stream = SpliceStream::new(plan, None);
    let mut ring = FrameRing::new();
    // Frames are dropped at once, so a chunk is always reclaimable.
    while let Some(frame) = stream.next_frame(ring.chunk(SPLICE_FRAME_ROOM)?) {
        drop(frame);
    }
    let (p, i) = stream.checksums()?;
    cache.put(key, p, i);
    Some((t0.elapsed(), bytes))
}

/// A `GPRE` stream with exactly one spliced pack (+ idx).
pub struct PrefetchStream {
    header: Option<Bytes>,
    splice: SpliceStream,
    cache: Arc<TrailerCache>,
    key: u64,
    total: u64,
}

impl PrefetchStream {
    pub fn new(
        plan: Plan,
        known: Option<([u8; 20], [u8; 20])>,
        cache: Arc<TrailerCache>,
        key: u64,
        buf: &mut BytesMut,
    ) -> Self {
        let total = 8u64
            .saturating_add(24)
            .saturating_add(plan.pack_len)
            .saturating_add(plan.idx_len);
        buf.extend_from_slice(GPRE_MAGIC);
        buf.extend_from_slice(&1u16.to_le_bytes());
        buf.extend_from_slice(&(plan.timestamp as i64).to_le_bytes());
        buf.extend_from_slice(&(plan.pack_len as i64).to_le_bytes());
        buf.extend_from_slice(&(plan.idx_len as i64).to_le_bytes());
        let header = buf.split().freeze();
        Self {
            header: Some(header),
            splice: SpliceStream::new(plan, known),
            cache,
            key,
            total,
        }
    }

    /// `GPRE` with zero packs (the client is up to date).
    pub fn empty() -> Bytes {
        Bytes::from_static(b"GPRE \x01\x00\x00")
    }

    fn next_frame(&mut self, ring: &mut FrameRing) -> Result<Option<Bytes>, Busy> {
        if let Some(h) = self.header.take() {
            return Ok(Some(h));
        }
        let buf = ring.chunk(SPLICE_FRAME_ROOM).ok_or(Busy)?;
        let frame = self.splice.next_frame(buf);
        // hyper stops polling once Content-Length is satisfied, so record the checksums
        // together with the last frame rather than on the trailing `None`.
        if self.splice.is_done()
            && !self.splice.plan().is_passthrough()
            && let Some((p, i)) = self.splice.checksums()
        {
            self.cache.put(self.key, p, i);
        }
        Ok(frame)
    }
}

/// A pack of planned entries (`POST /gvfs/objects`).
pub struct ObjectsStream {
    arena: ArenaGuard,
    cat: Arc<Catalog>,
    idx: usize,
    pos: u64,
    hash: Sha1,
    header_sent: bool,
    done: bool,
    exact: Option<u64>,
    /// A converted entry being deflated across polls.
    mid: Option<Deflating>,
    /// A zero-copy payload to emit right after its generated header.
    pending: Option<Bytes>,
}

impl ObjectsStream {
    pub fn new(arena: ArenaGuard, cat: Arc<Catalog>, exact: Option<u64>) -> Self {
        Self {
            arena,
            cat,
            idx: 0,
            pos: 12,
            hash: Sha1::new(),
            header_sent: false,
            done: false,
            exact,
            mid: None,
            pending: None,
        }
    }

    fn account(&mut self, b: Bytes) -> Bytes {
        self.hash.update(&b);
        self.pos = self.pos.saturating_add(b.len() as u64);
        b
    }

    fn next_frame(&mut self) -> Result<Option<Bytes>, Busy> {
        loop {
            if let Some(b) = self.pending.take() {
                return Ok(Some(self.account(b)));
            }
            if self.mid.is_some() {
                let ra = self.arena.get();
                let stepped = match self.mid.as_mut() {
                    Some(m) => m.step(ra)?,
                    None => None,
                };
                match stepped {
                    Some(f) => return Ok(Some(self.account(f))),
                    None => {
                        self.mid = None;
                        continue;
                    }
                }
            }
            if self.done {
                return Ok(None);
            }
            let ra = self.arena.get();
            if !self.header_sent {
                self.header_sent = true;
                let n = u32::try_from(ra.plan.len()).unwrap_or(u32::MAX);
                let h = pack_header(n);
                self.hash.update(h);
                let buf = ra.frames.chunk(h.len()).ok_or(Busy)?;
                buf.extend_from_slice(&h);
                return Ok(Some(buf.split().freeze()));
            }
            let Some(e) = ra.plan.get(self.idx).copied() else {
                self.done = true;
                let d: [u8; 20] = self.hash.clone().finalize().into();
                let buf = ra.frames.chunk(d.len()).ok_or(Busy)?;
                buf.extend_from_slice(&d);
                return Ok(Some(buf.split().freeze()));
            };
            let Some(slab) = self.cat.probe(usize::from(e.slab)).cloned() else {
                return Ok(None);
            };
            let loc = Loc {
                offset: e.offset,
                len: e.len,
            };
            let entry = slab
                .pack
                .slice(e.offset as usize..(e.offset as usize).saturating_add(e.len as usize));
            let Ok(h) = parse_entry_header(&entry) else {
                return Ok(None);
            };
            if ra.nums.len() <= self.idx {
                ra.nums.push(self.pos);
            } else if let Some(p) = ra.nums.get_mut(self.idx) {
                *p = self.pos;
            }
            self.idx = self.idx.saturating_add(1);
            if e.convert {
                // Resolve the chain into the arena; deflate it frame by frame from there.
                let mark = ra.bytes.mark();
                let mut inflater = ra.inflater.take().unwrap_or_default();
                let mut chain = core::mem::take(&mut ra.chain);
                let resolved = resolve_full(&slab, loc, &mut ra.bytes, &mut inflater, &mut chain);
                ra.inflater = Some(inflater);
                ra.chain = chain;
                let Ok((kind, content)) = resolved else {
                    ra.bytes.truncate(mark);
                    return Ok(None);
                };
                self.mid = Some(Deflating::pack_entry(kind, content, mark));
                continue;
            }
            if e.base != NO_BASE {
                // Re-encoded distance in a generated header; the delta bytes by reference.
                let Some(base_pos) = ra.nums.get(e.base as usize).copied() else {
                    return Ok(None);
                };
                let mut hdr = [0u8; 20];
                let hl =
                    encode_ofs_delta_header(h.size, self.pos.saturating_sub(base_pos), &mut hdr);
                let buf = ra.frames.chunk(hl).ok_or(Busy)?;
                buf.extend_from_slice(hdr.get(..hl).unwrap_or(&[]));
                let head = buf.split().freeze();
                self.pending = Some(entry.slice(h.header_len..));
                return Ok(Some(self.account(head)));
            }
            return Ok(Some(self.account(entry)));
        }
    }
}

/// A resolved loose object (`GET /gvfs/objects/{oid}` of a delta), deflated frame by frame.
pub struct LooseStream {
    arena: ArenaGuard,
    mid: Deflating,
}

impl LooseStream {
    pub fn new(arena: ArenaGuard, mid: Deflating) -> Self {
        Self { arena, mid }
    }

    fn next_frame(&mut self) -> Result<Option<Bytes>, Busy> {
        self.mid.step(self.arena.get())
    }
}

/// `[{"Id":"<oid>","Size":n},...]` for `POST /gvfs/sizes`.
pub struct SizesStream {
    arena: ArenaGuard,
    idx: usize,
    count: usize,
    oids_start: usize,
    done: bool,
}

impl SizesStream {
    pub fn new(arena: ArenaGuard, oids_start: usize, count: usize) -> Self {
        Self {
            arena,
            idx: 0,
            count,
            oids_start,
            done: false,
        }
    }

    /// Exact body length: `[` + entries joined by `,` + `]`.
    pub fn exact_len(&mut self) -> u64 {
        let ra = self.arena.get();
        let mut n = 2u64;
        for (i, size) in ra.nums.iter().enumerate().take(self.count) {
            // {"Id":"<40>","Size":<digits>}  = 7 + 40 + 9 + digits + 1
            n = n
                .saturating_add(57)
                .saturating_add(decimal_len(*size) as u64);
            if i > 0 {
                n = n.saturating_add(1);
            }
        }
        n
    }

    fn next_frame(&mut self) -> Result<Option<Bytes>, Busy> {
        if self.done {
            return Ok(None);
        }
        let ra = self.arena.get();
        // 1024 entries of at most 78 bytes each, plus the brackets.
        let buf = ra
            .frames
            .chunk(1024usize.saturating_mul(78).saturating_add(2))
            .ok_or(Busy)?;
        if self.idx == 0 {
            buf.extend_from_slice(b"[");
        }
        let end = self.count.min(self.idx.saturating_add(1024));
        for i in self.idx..end {
            let size = ra.nums.get(i).copied().unwrap_or(0);
            let at = self.oids_start.saturating_add(i.saturating_mul(20));
            let oid = ra.bytes.get(crate::arena::Span::new(at, 20));
            let mut hex = [0u8; 40];
            crate::oid::encode_hex(oid, &mut hex);
            if i > 0 {
                buf.extend_from_slice(b",");
            }
            buf.extend_from_slice(b"{\"Id\":\"");
            buf.extend_from_slice(&hex);
            buf.extend_from_slice(b"\",\"Size\":");
            let mut dec = [0u8; 20];
            let n = put_decimal(size, &mut dec);
            buf.extend_from_slice(dec.get(..n).unwrap_or(&[]));
            buf.extend_from_slice(b"}");
        }
        self.idx = end;
        if self.idx >= self.count {
            buf.extend_from_slice(b"]");
            self.done = true;
        }
        Ok(Some(buf.split().freeze()))
    }
}

/// Up to three fixed frames (a spliced loose object: prefix, payload, trailer); the arena
/// that staged them is held until they are sent.
pub struct FramesBody {
    frames: [Option<Bytes>; 3],
    i: usize,
    _arena: Option<ArenaGuard>,
}

pub enum Body {
    Empty,
    Full(Option<Bytes>),
    Frames(Box<FramesBody>),
    Prefetch(Box<(PrefetchStream, FrameRing)>),
    Objects(Box<ObjectsStream>),
    Loose(Box<LooseStream>),
    Sizes(Box<SizesStream>, u64),
}

impl Body {
    pub fn full(b: Bytes) -> Self {
        Self::Full(Some(b))
    }

    pub fn text(s: &'static str) -> Self {
        Self::Full(Some(Bytes::from_static(s.as_bytes())))
    }

    pub fn frames(a: Bytes, b: Bytes, c: Bytes, arena: Option<ArenaGuard>) -> Self {
        Self::Frames(Box::new(FramesBody {
            frames: [Some(a), Some(b), Some(c)],
            i: 0,
            _arena: arena,
        }))
    }

    pub fn prefetch(s: PrefetchStream) -> Self {
        Self::Prefetch(Box::new((s, FrameRing::new())))
    }

    pub fn objects(s: ObjectsStream) -> Self {
        Self::Objects(Box::new(s))
    }

    pub fn loose(s: LooseStream) -> Self {
        Self::Loose(Box::new(s))
    }

    pub fn sizes(mut s: SizesStream) -> Self {
        let len = s.exact_len();
        Self::Sizes(Box::new(s), len)
    }
}

impl HttpBody for Body {
    type Data = Bytes;
    type Error = Infallible;

    fn poll_frame(
        self: Pin<&mut Self>,
        cx: &mut Context<'_>,
    ) -> Poll<Option<Result<Frame<Bytes>, Infallible>>> {
        let _hot = gvfs_alloc_guard::HotPathGuard::enter();
        let this = self.get_mut();
        let next = match this {
            Body::Empty => Ok(None),
            Body::Full(b) => Ok(b.take()),
            Body::Frames(fb) => {
                let mut out = None;
                while out.is_none() && fb.i < fb.frames.len() {
                    out = fb.frames.get_mut(fb.i).and_then(Option::take);
                    fb.i = fb.i.saturating_add(1);
                }
                Ok(out)
            }
            Body::Prefetch(p) => {
                let (s, ring) = &mut **p;
                s.next_frame(ring)
            }
            Body::Objects(s) => s.next_frame(),
            Body::Loose(s) => s.next_frame(),
            Body::Sizes(s, _) => s.next_frame(),
        };
        match next {
            Ok(next) => Poll::Ready(next.map(|b| Ok(Frame::data(b)))),
            Err(Busy) => {
                // Every staging chunk is in flight: let hyper write, then try again.
                cx.waker().wake_by_ref();
                Poll::Pending
            }
        }
    }

    fn is_end_stream(&self) -> bool {
        match self {
            Body::Empty => true,
            Body::Full(b) => b.is_none(),
            Body::Frames(fb) => fb.frames.iter().skip(fb.i).all(Option::is_none),
            Body::Prefetch(..) | Body::Objects(..) | Body::Loose(..) | Body::Sizes(..) => false,
        }
    }

    fn size_hint(&self) -> SizeHint {
        match self {
            Body::Empty => SizeHint::with_exact(0),
            Body::Full(b) => SizeHint::with_exact(b.as_ref().map_or(0, |b| b.len() as u64)),
            Body::Frames(fb) => SizeHint::with_exact(
                fb.frames
                    .iter()
                    .skip(fb.i)
                    .flatten()
                    .map(|b| b.len() as u64)
                    .sum(),
            ),
            Body::Prefetch(p) => SizeHint::with_exact(p.0.total),
            Body::Objects(s) => s.exact.map_or_else(SizeHint::default, SizeHint::with_exact),
            Body::Loose(_) => SizeHint::default(),
            Body::Sizes(_, len) => SizeHint::with_exact(*len),
        }
    }
}
